insert into public.internal_notes (evidence_code, company_id, related_interaction_id, note_date, author, note_text, tags) values
  ('NOTE_001', (select company_id from public.company_master where company_code = 'CLI_001'), (select interaction_id from public.client_interactions where evidence_code = 'INT_001'), '2026-06-17', 'Dana Whitfield', 'Quarterly relationship review with Walmart''s regional treasury team went well overall -- the core banking relationship remains one of our strongest by revenue, with steady growth across payments, treasury services, and liquidity management over the past two years. That said, this call was specifically with the regional treasury contacts, not the corporate capital-markets or corporate development functions, so I do not have direct visibility into how the recently reported large capital-markets activity is being financed or which banks are involved. The attendees present were not able to speak to it and I did not want to press given the audience. The existing corporate financing facility opportunity in our pipeline is unrelated and moving along its own timeline. Given the size and profile of the reported activity, it is worth getting a meeting with the corporate development or capital-markets contacts specifically to understand whether there is a role for us, but I do not have that evidence yet from this call.', ARRAY['ext_sig_insufficient_data', 'flagship']::text[]),
  ('NOTE_002', (select company_id from public.company_master where company_code = 'CLI_001'), NULL, '2025-05-17', 'Priya Raman', 'No new competitive activity or concerns were raised by the client during this conversation. The team confirmed their point of contact structure remains unchanged since our last interaction. Dana Whitfield flagged no changes to the account''s risk profile based on this conversation. The conversation touched briefly on treasury_services usage, which remains consistent with prior quarters. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. Dana Whitfield reviewed recent transaction volumes across the account and confirmed nothing unusual to report. The client did not raise any pending decisions that would require escalation on our side. Met with Walmart''s finance team for a regular relationship check-in covering current account activity. Overall tone of the conversation was professional and consistent with the account''s established cadence. We discussed general market conditions in the Retail sector without specific implications for the account. Follow-up items from this conversation are limited to routine documentation updates. Dana Whitfield noted that the executive sponsor relationship remains healthy and responsive.', ARRAY['routine']::text[]),
  ('NOTE_003', (select company_id from public.company_master where company_code = 'CLI_001'), NULL, '2026-01-12', 'Naomi Kessler', 'Follow-up items from this conversation are limited to routine documentation updates. The conversation touched briefly on fx usage, which remains consistent with prior quarters. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. Dana Whitfield flagged no changes to the account''s risk profile based on this conversation. The client did not raise any pending decisions that would require escalation on our side. The team confirmed their point of contact structure remains unchanged since our last interaction. Met with Walmart''s finance team for a regular relationship check-in covering current account activity. We discussed general market conditions in the Retail sector without specific implications for the account. Overall tone of the conversation was professional and consistent with the account''s established cadence. Dana Whitfield reviewed recent transaction volumes across the account and confirmed nothing unusual to report. Dana Whitfield noted that the executive sponsor relationship remains healthy and responsive. No new competitive activity or concerns were raised by the client during this conversation.', ARRAY['routine']::text[]),
  ('NOTE_004', (select company_id from public.company_master where company_code = 'CLI_001'), NULL, '2026-02-04', 'Dana Whitfield', 'No new competitive activity or concerns were raised by the client during this conversation. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. Met with Walmart''s finance team for a regular relationship check-in covering current account activity. The conversation touched briefly on liquidity_management usage, which remains consistent with prior quarters. The team confirmed their point of contact structure remains unchanged since our last interaction. The client did not raise any pending decisions that would require escalation on our side. We discussed general market conditions in the Retail sector without specific implications for the account. Dana Whitfield noted that the executive sponsor relationship remains healthy and responsive. Follow-up items from this conversation are limited to routine documentation updates. Dana Whitfield flagged no changes to the account''s risk profile based on this conversation. Dana Whitfield reviewed recent transaction volumes across the account and confirmed nothing unusual to report. Overall tone of the conversation was professional and consistent with the account''s established cadence.', ARRAY['routine']::text[]),
  ('NOTE_005', (select company_id from public.company_master where company_code = 'CLI_001'), NULL, '2025-01-02', 'Fiona Ondrej', 'The client did not raise any pending decisions that would require escalation on our side. Overall tone of the conversation was professional and consistent with the account''s established cadence. Follow-up items from this conversation are limited to routine documentation updates. Dana Whitfield flagged no changes to the account''s risk profile based on this conversation. The team confirmed their point of contact structure remains unchanged since our last interaction. Dana Whitfield reviewed recent transaction volumes across the account and confirmed nothing unusual to report. No new competitive activity or concerns were raised by the client during this conversation. Dana Whitfield noted that the executive sponsor relationship remains healthy and responsive. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. The conversation touched briefly on lending usage, which remains consistent with prior quarters. Met with Walmart''s finance team for a regular relationship check-in covering current account activity. We discussed general market conditions in the Retail sector without specific implications for the account.', ARRAY['routine']::text[]),
  ('NOTE_006', (select company_id from public.company_master where company_code = 'CLI_001'), NULL, '2025-03-17', 'Grant Elias', 'Met with Walmart''s finance team for a regular relationship check-in covering current account activity. Follow-up items from this conversation are limited to routine documentation updates. The client did not raise any pending decisions that would require escalation on our side. The team confirmed their point of contact structure remains unchanged since our last interaction. Dana Whitfield reviewed recent transaction volumes across the account and confirmed nothing unusual to report. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. We discussed general market conditions in the Retail sector without specific implications for the account. Overall tone of the conversation was professional and consistent with the account''s established cadence. The conversation touched briefly on payments usage, which remains consistent with prior quarters. No new competitive activity or concerns were raised by the client during this conversation. Dana Whitfield noted that the executive sponsor relationship remains healthy and responsive. Dana Whitfield flagged no changes to the account''s risk profile based on this conversation.', ARRAY['routine']::text[]),
  ('NOTE_007', (select company_id from public.company_master where company_code = 'CLI_002'), (select interaction_id from public.client_interactions where evidence_code = 'INT_011'), '2026-06-25', 'Marcus Ibe', 'Difficult call today following the confirmation that we lost the warehouse-network refinancing mandate to Meridian Capital Partners. This is the second competitive loss with this client in the past two quarters and the pattern is becoming concerning. Their treasury lead was candid that Meridian has been more aggressive on pricing and, more worryingly, has staffed a dedicated coverage team that meets with Amazon''s logistics finance group monthly -- something we have not matched. Transaction volumes on our core payments book are still solid, but treasury services revenue has been declining for three straight quarters and the trade finance renewal is now stalled pending a competing proposal. On a positive note, the FX desk relationship remains strong and that product line is actually growing, so this is not a uniform collapse -- it looks more like a competitive incursion specifically around lending and capital markets. Recommend an executive-to-executive relationship review before the next renewal cycle; we risk losing meaningful additional wallet share if Meridian''s coverage model continues to outpace ours here.', ARRAY['ext_neg_int_neg', 'flagship']::text[]),
  ('NOTE_008', (select company_id from public.company_master where company_code = 'CLI_002'), NULL, '2024-11-20', 'Marcus Ibe', 'Follow-up items from this conversation are limited to routine documentation updates. Marcus Ibe flagged no changes to the account''s risk profile based on this conversation. The client did not raise any pending decisions that would require escalation on our side. Met with Amazon''s finance team for a regular relationship check-in covering current account activity. No new competitive activity or concerns were raised by the client during this conversation. Overall tone of the conversation was professional and consistent with the account''s established cadence. Marcus Ibe noted that the executive sponsor relationship remains healthy and responsive. We discussed general market conditions in the E-Commerce & Cloud Services sector without specific implications for the account. Marcus Ibe reviewed recent transaction volumes across the account and confirmed nothing unusual to report. The team confirmed their point of contact structure remains unchanged since our last interaction. We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. The conversation touched briefly on capital_markets usage, which remains consistent with prior quarters.', ARRAY['routine']::text[]),
  ('NOTE_009', (select company_id from public.company_master where company_code = 'CLI_002'), NULL, '2024-10-03', 'Marcus Ibe', 'We confirmed the next scheduled touchpoint and agreed on standard follow-up cadence. Met with Amazon''s finance team for a regular relationship check-in covering current account activity. We discussed general market conditions in the E-Commerce & Cloud Services sector without specific implications for the account. The conversation touched briefly on lending usage, which remains consistent with prior quarters. No new competitive activity or concerns were raised by the client during this conversation. Marcus Ibe flagged no changes to the account''s risk profile based on this conversation. The client did not raise any pending decisions that would require escalation on our side. Follow-up items from this conversation are limited to routine documentation updates. The team confirmed their point of contact structure remains unchanged since our last interaction. Marcus Ibe reviewed recent transaction volumes across the account and confirmed nothing unusual to report. Overall tone of the conversation was professional and consistent with the account''s established cadence. Marcus Ibe noted that the executive sponsor relationship remains healthy and responsive.', ARRAY['routine']::text[]),
